const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',light:'M9 18h6 M10 21h4 M8 14a6 6 0 1 1 8 0l-1 2H9z',fan:'M12 12c-9-1-9-10-3-10 5 0 4 7 3 10z M12 12c5-7 13-3 10 2-3 4-8 0-10-2z M12 12c4 8-3 14-6 9-3-5 4-8 6-9z',energy:'M13 2L4 14h7l-1 8 10-13h-8z',leaf:'M20 3C8 1 1 9 6 16s16 2 14-13z M5 21l10-12',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12z',sun:'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',film:'M3 5h18v14H3z M7 5v14 M17 5v14 M3 9h4 M3 15h4 M17 9h4 M17 15h4',away:'M9 4H3v16h6 M10 12h12 M17 7l5 5-5 5',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',plus:'M12 5v14 M5 12h14',print:'M6 8V3h12v5 M6 17H3V9h18v8h-3 M6 14h12v7H6z',tablet:'M5 2h14v20H5z M11 18h2',plug:'M8 2v5 M16 2v5 M5 7h14v5a7 7 0 0 1-14 0z M12 19v3',climate:'M10 14V4a2 2 0 0 1 4 0v10a4 4 0 1 1-4 0 M12 9v8',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',check:'M5 12l4 4L19 6',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.grid}"/></svg>`;
const initial=[{id:1,name:'Pendant lights',room:'Living room',type:'light',on:true,value:75,temp:3200,color:'#edc780',watts:36},{id:2,name:'Ceiling fan',room:'Living room',type:'fan',on:true,value:45,watts:70},{id:3,name:'Ambient LED strip',room:'Living room',type:'light',on:true,value:60,temp:4000,color:'#a1c985',watts:24},{id:4,name:'Smart thermostat',room:'Living room',type:'climate',on:true,value:23,watts:1200},{id:5,name:'Bedside lamp',room:'Bedroom',type:'light',on:false,value:40,temp:2700,color:'#edc780',watts:12},{id:6,name:'Bedroom fan',room:'Bedroom',type:'fan',on:false,value:30,watts:65},{id:7,name:'Counter lights',room:'Kitchen',type:'light',on:true,value:85,temp:4500,color:'#fff2c5',watts:30},{id:8,name:'Coffee station',room:'Kitchen',type:'plug',on:false,value:100,watts:850},{id:9,name:'Wall tablet',room:'Office',type:'tablet',on:true,value:80,watts:15},{id:10,name:'Desk lamp',room:'Office',type:'light',on:false,value:65,temp:4200,color:'#fff2c5',watts:15}];
let devices=structuredClone(initial),view='Overview',room='All rooms',scene='',prefs={control:'slider',compact:false},events=['Living room scene activated','Heartly hub connected'],period='Today',billing='monthly';
try{prefs={...prefs,...JSON.parse(localStorage.getItem('heartly-preferences')||'{}')}}catch{}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function watts(d){return d.on?d.watts*(d.type==='climate'?.55:d.type==='plug'?1:d.value/100):0}function total(){return devices.reduce((s,d)=>s+watts(d),0)}function full(){return devices.reduce((s,d)=>s+d.watts,0)}function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3200)}
function chart(big=false){return `<div class="chart ${big?'big-chart':''}" role="img" aria-label="Illustrative energy use by hour">${[27,20,16,24,33,50,72,57,85,68,43,30].map((v,i)=>`<div class="bar" style="height:${Math.max(4,v*(.55+total()/3000))}%" title="${i*2}:00 · illustrative usage"></div>`).join('')}</div><div class="axis"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span></div>`}
function range(d,key,label,min,max,unit){return `<div class="slider-label"><span>${label}</span><output id="out-${d.id}-${key}">${d[key]}${unit}</output></div>${prefs.control==='slider'?`<input aria-label="${esc(d.name)} ${label}" type="range" min="${min}" max="${max}" step="${key==='temp'?100:1}" value="${d[key]}" data-id="${d.id}" data-key="${key}" data-unit="${unit}">`:`<div class="number-control"><button aria-label="Decrease ${esc(d.name)} ${label}" data-step="-${key==='temp'?100:1}" data-id="${d.id}" data-key="${key}" data-min="${min}" data-max="${max}">−</button><span>${min}–${max}${unit}</span><button aria-label="Increase ${esc(d.name)} ${label}" data-step="${key==='temp'?100:1}" data-id="${d.id}" data-key="${key}" data-min="${min}" data-max="${max}">+</button></div>`}`}
function card(d){return `<article class="device ${d.on?'':'off'}"><div class="device-top"><div class="device-icon" style="${d.type==='light'&&d.on?`background:${d.color}30;color:#69734b`:''}">${icon(d.type)}</div><button class="switch" role="switch" aria-label="${esc(d.name)} power" aria-checked="${d.on}" data-toggle="${d.id}"></button></div><h3>${esc(d.name)}</h3><p>${esc(d.room)} · ${d.on?'On':'Off'}</p>${d.type==='light'?range(d,'value','Brightness',0,100,'%')+range(d,'temp','Color temperature',2200,6500,' K')+`<div class="color-row"><span>Light color</span><div class="swatches">${['#edc780','#fff2c5','#a1c985','#98c4e4','#bd9bdd'].map(c=>`<button class="swatch" aria-label="Set ${esc(d.name)} color ${c}" data-color="${c}" data-id="${d.id}" style="background:${c};${d.color===c?'outline:2px solid #416346':''}"></button>`).join('')}<input type="color" aria-label="Custom color for ${esc(d.name)}" value="${d.color}" data-id="${d.id}"></div></div>`:d.type==='fan'?range(d,'value','Fan speed',0,100,'%')+`<div class="color-row"><span>Airflow</span><b>${d.value<35?'Gentle':d.value<70?'Balanced':'Powerful'}</b></div>`:d.type==='climate'?range(d,'value','Target temperature',16,30,'°C')+'<div class="color-row"><span>Room temperature</span><b>24.5°C</b></div>':d.type==='tablet'?range(d,'value','Display brightness',0,100,'%')+'<div class="color-row"><span>Display</span><b>Home dashboard</b></div>':'<div class="color-row"><span>Outlet capacity</span><b>850 W</b></div>'}<div class="device-footer"><span id="watts-${d.id}">${Math.round(watts(d))} W</span><button data-timer="${d.id}">${icon('clock').replace('<svg','<svg style="width:12px;height:12px;vertical-align:middle"')} ${d.until?'Timer set':'Set timer'}</button></div></article>`}
function scenes(){return `<div class="section-heading"><h2>A little mood, one tap away</h2><span>Scenes</span></div><div class="scene-row">${[['sun','Good morning','A brighter start'],['film','Movie time','Settle into the evening'],['moon','Good night','Let your home rest'],['away','Away','Save while you’re out']].map(([i,n,s])=>`<button class="scene ${scene===n?'selected':''}" data-scene="${n}" aria-pressed="${scene===n}"><span class="icon">${icon(i)}</span><span><b>${n}</b><small>${s}</small></span></button>`).join('')}</div>`}
function energyRail(){return `<div class="rail-card"><div class="section-heading"><h2>Energy at a glance</h2>${icon('energy')}</div><div class="energy-total" id="daily">${(total()*8/1000).toFixed(2)} <small>kWh / 8 hours</small></div><span class="muted" style="font-size:12px">At your current device settings</span>${chart()}<div class="energy-key"><span>Estimated cost</span><b id="cost">₹${(total()*8/1000*8).toFixed(2)}</b></div></div><div class="rail-card saving">${icon('leaf')}<h3>A little less energy. A lot more care.</h3><p id="saving">Your settings use ${Math.round((1-total()/full())*100)}% less power than all devices at full output.</p></div><div class="rail-card"><h2>Around your home</h2>${events.slice(0,3).map((e,i)=>`<div class="event">${icon(i?'home':'check')}<div>${esc(e)}<small>${i?'Demo activity':'Just now'}</small></div></div>`).join('')}</div>`}
function dashboard(){return `<div class="overview"><div class="welcome"><div class="eyebrow">HOME, IN HARMONY</div><h2>A comfortable home.<br>A lighter footprint.</h2><small>Everything you need, a touch away.</small><div class="weather">${icon('sun')}</div></div><div class="stat"><div class="stat-head">${icon('plug')} Devices at work</div><strong id="active-count">${devices.filter(d=>d.on).length} <small>/ ${devices.length} devices</small></strong><p>Connected in this demo</p></div><div class="stat"><div class="stat-head">${icon('energy')} Power right now</div><strong id="power">${(total()/1000).toFixed(2)} <small>kW</small></strong><p>Updates as you adjust your home</p></div></div>${scenes()}<div class="workspace"><section><div class="section-heading"><h2>Your devices <span>(${devices.length})</span></h2><button data-master="true" style="font-size:12px;padding:6px 10px">${devices.some(d=>d.on)?'Turn all off':'Turn all on'}</button></div><div class="room-tabs" aria-label="Filter by room">${['All rooms','Living room','Bedroom','Kitchen','Office'].map(r=>`<button data-room="${r}" class="${room===r?'active':''}" aria-pressed="${room===r}">${r}</button>`).join('')}</div><div class="devices">${devices.filter(d=>room==='All rooms'||d.room===room).map(card).join('')||'<div class="empty">No devices in this room yet.</div>'}</div></section><section class="rail" aria-label="Energy and activity">${energyRail()}</section></div>`}
function energyView(){let factor=period==='Today'?1:period==='Week'?7:30;return `<div class="room-tabs">${['Today','Week','Month'].map(p=>`<button data-period="${p}" class="${period===p?'active':''}">${p}</button>`).join('')}</div><div class="overview"><div class="stat"><div class="stat-head">Projected consumption</div><strong>${(total()*8*factor/1000).toFixed(2)} <small>kWh</small></strong><p>8 operating hours per day</p></div><div class="stat"><div class="stat-head">Projected cost</div><strong>₹${(total()*8*factor/1000*8).toFixed(0)}</strong><p>Illustrative tariff: ₹8 / kWh</p></div><div class="stat"><div class="stat-head">Potential savings</div><strong>₹${((full()-total())*8*factor/1000*8).toFixed(0)}</strong><p>Versus all devices at full power</p></div></div><div class="workspace"><div class="rail-card"><h2>Your daily energy rhythm</h2><p class="footnote">Illustrative hourly pattern, scaled to current power. This is not meter history.</p>${chart(true)}<h2 style="margin-top:35px">Where your power goes</h2>${devices.map(d=>`<div class="energy-key"><span>${esc(d.name)}</span><b>${Math.round(watts(d))} W</b></div>`).join('')}</div><div>${energyRail()}</div></div>`}
function systemView(){return `<div class="welcome" style="margin-bottom:24px"><div class="eyebrow">MEET HEARTLY</div><h2 style="max-width:none">One home. One thoughtful system.</h2><p style="margin-bottom:0;color:#d7e6dc">Lighting, comfort, control and energy awareness, brought together.</p></div><div class="view-grid">${[['home','The idea','Give every room an intuitive control surface. Adjust individual devices or coordinate your home with one scene.'],['grid','The system','A home hub connects compatible devices to a responsive dashboard on a phone, tablet, laptop or wall display.'],['leaf','The impact','See how device choices affect power use. Explore consumption and savings before deciding what to automate.']].map(([i,n,p])=>`<article class="rail-card large">${icon(i)}<h2 style="margin:18px 0">${n}</h2><p>${p}</p></article>`).join('')}</div><div class="rail-card large"><h2>From a tap to a more comfortable room</h2><p style="margin-top:20px">1. Choose a device or scene → 2. Adjust your preferences → 3. See device state and energy estimates update.</p><p>This browser demo simulates a connected home. Real device discovery, hub integration, secure remote access and measured energy data require a production backend and compatible hardware.</p><button class="primary" data-nav="Overview">Explore the demo</button></div>`}
function pricingView(){return `<p class="muted" style="font-size:14px;margin-bottom:25px">Illustrative plans for the Heartly concept. No payments or subscriptions are collected.</p><div class="room-tabs"><button data-billing="monthly" class="${billing==='monthly'?'active':''}">Monthly</button><button data-billing="annual" class="${billing==='annual'?'active':''}">Annual · save 20%</button></div><div class="view-grid">${[['Explore',0,'Try a smarter home',['Interactive browser demo','All simulated device types','Custom controls and print reports']],['Home',299,'Everyday comfort, connected',['Concept: up to 30 devices','Concept: scenes and schedules','Concept: household energy insights']],['Home Plus',599,'Room to make it yours',['Concept: unlimited devices','Concept: multiple properties','Concept: advanced energy reports']]].map(([n,p,s,features])=>`<article class="rail-card large" style="${n==='Home'?'border:2px solid #527847':''}"><span class="pill">${n==='Home'?'For the whole home':n}</span><h2 style="margin-top:20px">${n}</h2><p>${s}</p><div class="price">₹${billing==='annual'?Math.round(p*.8):p}<small> / month${billing==='annual'&&p?' · billed yearly':''}</small></div><ul>${features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="${n==='Home'?'primary':''}" data-plan="${n}">${p?'View concept plan':'Try the demo'}</button></article>`).join('')}</div>`}
function render(){app.innerHTML=`<div class="shell ${prefs.compact?'compact':''}"><aside><div class="brand"><b>h</b> heartly<span style="color:#7f9a6a">.</span></div><div class="home-switch">${icon('home')}<div><strong style="font-size:14px">The Heartly home</strong><small>Interactive demo</small></div></div><p class="nav-label">YOUR SPACE</p><nav>${[['Overview','grid'],['Energy','energy'],['The system','home'],['Pricing','plug']].map(([n,i])=>`<button data-nav="${n}" class="${view===n?'active':''}" ${view===n?'aria-current="page"':''}>${icon(i)}${n}</button>`).join('')}</nav><div class="side-bottom"><div class="demo-box">Make yourself at home.<p>Try every control. All devices here are simulated.</p></div><div class="avatar"><b>JD</b><span>Guest explorer<small>Your personal demo</small></span></div></div></aside><main class="main"><header class="topbar"><span>My home <span style="color:#b2bbb5;margin:0 12px">/</span> <b>${view}</b></span><div class="right"><span class="pill"><i class="dot"></i> Demo mode</span><span class="muted">Home, in harmony</span></div></header><div class="content"><div class="heading"><div><h1>${view==='Overview'?'Welcome home.':view==='Energy'?'Small changes. Measurable impact.':view==='Pricing'?'A home that grows with you.':'Thoughtfully connected.'}</h1><p class="muted">${view==='Overview'?'Your space, just the way you like it.':view==='Energy'?'Explore the energy behind your everyday comfort.':view==='Pricing'?'Explore a plan for every kind of home.':'The Heartly concept, from control to comfort.'}</p></div><div class="actions"><button data-print>${icon('print')} Print</button>${view==='Overview'?`<button data-customize>${icon('settings')} Customize</button><button class="primary" data-add>${icon('plus')} Add device</button>`:''}</div></div>${view==='Overview'?dashboard():view==='Energy'?energyView():view==='Pricing'?pricingView():systemView()}<p class="footnote">Heartly interactive demo · Simulated devices and estimates. Changes reset on reload; layout preferences stay in this browser.${view==='Energy'?' Savings compare current settings with all listed devices at rated power for the same 8-hour daily duration.':''}</p></div></main></div>`}
function log(s){events.unshift(s);events=events.slice(0,3)}function updateStats(){const vals={'power':`${(total()/1000).toFixed(2)} <small>kW</small>`,'daily':`${(total()*8/1000).toFixed(2)} <small>kWh / 8 hours</small>`,'cost':`₹${(total()*8/1000*8).toFixed(2)}`,'saving':`Your settings use ${Math.round((1-total()/full())*100)}% less power than all devices at full output.`};Object.entries(vals).forEach(([id,s])=>{let el=document.getElementById(id);if(el)el.innerHTML=s})}
function openModal(html){modal.innerHTML=html;modal.showModal()}function closeButtons(){return '<div class="actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save</button></div>'}
app.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let x=b.dataset;
if(x.nav){view=x.nav;render();window.scrollTo(0,0)}
else if(x.room){room=x.room;render()}
else if(x.toggle){let d=devices.find(d=>d.id==x.toggle);d.on=!d.on;scene='';log(`${d.name} turned ${d.on?'on':'off'}`);render()}
else if(x.master){let on=!devices.some(d=>d.on);devices.forEach(d=>d.on=on);scene='';log(`All devices turned ${on?'on':'off'}`);render();toast(`All devices are ${on?'on':'off'}`)}
else if(x.scene){scene=x.scene;devices.forEach(d=>{d.on=scene==='Good morning'||scene==='Movie time'&&d.room==='Living room';if(d.type==='light'){d.value=scene==='Movie time'?20:80;d.temp=scene==='Movie time'?2700:4200}else if(d.type==='fan')d.value=40});log(`${scene} scene activated`);render();toast(`${scene} applied to your home`)}
else if(x.color){devices.find(d=>d.id==x.id).color=x.color;render()}
else if(x.step){let d=devices.find(d=>d.id==x.id);d[x.key]=Math.max(+x.min,Math.min(+x.max,d[x.key]+ +x.step));scene='';render()}
else if('print'in x)window.print();
else if(x.period){period=x.period;render()}
else if(x.billing){billing=x.billing;render()}
else if(x.plan){if(x.plan==='Explore'){view='Overview';render()}else openModal(`<h2>${x.plan} concept plan</h2><p>These are proposed Heartly features and illustrative prices. This demo does not activate a subscription or charge you.</p><button data-close class="primary">Back to plans</button>`)}
else if('customize'in x)openModal(`<form id="preferences"><h2>Make it feel like your home</h2><label for="control">Device controls</label><select id="control" name="control"><option value="slider" ${prefs.control==='slider'?'selected':''}>Sliders — smooth adjustments</option><option value="step" ${prefs.control==='step'?'selected':''}>Step buttons — precise adjustments</option></select><label><input name="compact" type="checkbox" ${prefs.compact?'checked':''}> Compact device cards</label><p class="footnote">Saved only in this browser.</p>${closeButtons()}</form>`);
else if('add'in x)openModal(`<form id="add-device"><h2>Add a demo device</h2><label for="name">Device name</label><input id="name" name="name" required maxlength="45" placeholder="e.g. Reading light"><label for="type">Device type</label><select id="type" name="type"><option value="light">Color light / LED strip</option><option value="fan">Fan</option><option value="climate">Thermostat</option><option value="tablet">Tablet display</option><option value="plug">Smart plug</option></select><label for="room">Room</label><select id="room" name="room">${['Living room','Bedroom','Kitchen','Office'].map(r=>`<option>${r}</option>`).join('')}</select>${closeButtons()}</form>`);
else if(x.timer){let d=devices.find(d=>d.id==x.timer);openModal(`<form id="timer" data-id="${d.id}"><h2>${esc(d.name)} timer</h2><p>Turn this device off after a duration. Keep this demo tab open for the timer to run.</p><label for="minutes">Duration in minutes</label><input id="minutes" name="minutes" type="number" min="1" max="1440" value="30" required>${d.until?'<button type="button" data-cancel-timer="'+d.id+'">Remove existing timer</button>':''}${closeButtons()}</form>`)}});
app.addEventListener('input',e=>{let x=e.target.dataset;if(!x.id)return;let d=devices.find(d=>d.id==x.id);if(e.target.type==='color'){d.color=e.target.value;return}if(x.key){d[x.key]=+e.target.value;scene='';document.getElementById(`out-${d.id}-${x.key}`).textContent=d[x.key]+x.unit;document.getElementById(`watts-${d.id}`).textContent=Math.round(watts(d))+' W';updateStats()}});
app.addEventListener('change',e=>{if(e.target.matches('input[type=range],input[type=color]'))render()});
modal.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if('close'in b.dataset)modal.close();if(b.dataset.cancelTimer){let d=devices.find(d=>d.id==b.dataset.cancelTimer);d.until=null;modal.close();render();toast('Timer removed')}});
modal.addEventListener('submit',e=>{e.preventDefault();const f=e.target,data=new FormData(f);if(f.id==='preferences'){prefs={control:data.get('control'),compact:data.has('compact')};try{localStorage.setItem('heartly-preferences',JSON.stringify(prefs))}catch{}toast('Your layout is ready')}
if(f.id==='add-device'){let name=data.get('name').trim();if(!name){document.getElementById('name').setCustomValidity('Enter a device name');return}let type=data.get('type');devices.push({id:Date.now(),name,room:data.get('room'),type,on:false,value:type==='climate'?23:50,temp:3200,color:'#a1c985',watts:{light:24,fan:70,climate:1200,tablet:15,plug:850}[type]});room=data.get('room');log(`${name} added`);toast('Demo device added')}
if(f.id==='timer'){let d=devices.find(d=>d.id==f.dataset.id);d.until=Date.now()+Number(data.get('minutes'))*60000;toast(`Timer set for ${data.get('minutes')} minutes`)}modal.close();render()});
setInterval(()=>{let expired=devices.filter(d=>d.until&&Date.now()>=d.until);if(expired.length){expired.forEach(d=>{d.on=false;d.until=null;log(`${d.name} timer completed`)});render();toast('Timer completed — device turned off')}},1000);
render();
